function batteryPage(o,x){"use strict";var d=[{v:0,rgb:[195,0,0]},{v:.15,rgb:[240,170,0]},{v:.25,rgb:[30,128,0]},{v:1,rgb:[30,128,0]}],m=document.getElementById(o.textElement),c=document.getElementById(o.widgetPercentElement),l=document.getElementById(o.widgetBatteryElement);u().then(e=>{var r="";if(c.textContent="",l.textContent="",e.errCode)switch(e.errCode){case 1:r="Your browser doesn't provide the Battery Status API.";break;case 2:r="Sorry, an error occurred on this page.";break}else if(e.level){let t=b(d,e.level);r=`<div>Level <b>${(e.level*100).toFixed(0)}%</b></div><div>Discharging Time: ${e.dischargingTime} s</div><div>Charging Time: <b>${v(e.chargingTime)}</b></div><div>Estimated Time to Discharge: <b>${v(e.dischargingTime)}</b></div>`,c.textContent=`${(e.level*100).toFixed(0)}% ${e.charging?", charging":""}`,l.innerHTML=`<div style="height: 30px; width: 150px; border-radius: 5px; border: 5px solid ${t}; padding: 3pt; margin: 0 auto;"><b style="display: block; height: 100%; width: ${(e.level*100).toFixed(0)}%; background-color: ${t};"></b></div>`}m.innerHTML=r});async function u(){const e={level:null,charging:"n/a",chargingTime:"n/a",dischargingTime:"n/a"};if(!navigator.getBattery||typeof navigator.getBattery!="function")return e.errCode=1,e;try{const r=await navigator.getBattery();return{level:Number.isFinite(r.level)?r.level:null,charging:r.charging,chargingTime:Number.isFinite(r.chargingTime)?r.chargingTime:"n/a",dischargingTime:Number.isFinite(r.dischargingTime)?r.dischargingTime:"n/a"}}catch{return e.errCode=2,e}}function v(e){if(typeof e!="number"||!Number.isFinite(e)||e<0)return"n/a";if(e=Math.floor(e),e<60)return`${e} seconds`;const r=Math.floor(e/86400),t=Math.floor(e%86400/3600),g=Math.floor(e%3600/60),n=e%60;let i;switch(r){case 0:i="";break;case 1:i="1 day ";break;default:i=`${r} days `}return`${i}${String(t).padStart(2,"0")}:${String(g).padStart(2,"0")}:${String(n).padStart(2,"0")}`}function b(e,r){const t=[...e].sort((a,s)=>a.v-s.v);if(r<=t[0].v)return`rgb(${t[0].rgb.join(", ")})`;const g=t[t.length-1];if(r>=g.v)return`rgb(${g.rgb.join(", ")})`;let n=0;for(;r>t[n+1].v;)n++;const i=t[n],h=t[n+1],y=(r-i.v)/(h.v-i.v),[f,T,$]=i.rgb.map((a,s)=>Math.round(a+(h.rgb[s]-a)*y));return`rgb(${f}, ${T}, ${$})`}}
